import java.util.Comparator;

final class BinarySearch {
    private static final SearchContainer<Integer> CONTAINER = SearchContainer.defaultContainer();

    private BinarySearch() {
    }

    static int binarySearch(int[] sortedArray, int target) {
        return CONTAINER.searchAlgorithm().search(toIntegerArray(sortedArray), target).index();
    }

    static <T extends Comparable<? super T>> int binarySearch(T[] sortedArray, T target) {
        return SearchContainer.<T>naturalOrderContainer()
                .searchAlgorithm()
                .search(sortedArray, target)
                .index();
    }

    static <T> int binarySearch(
            T[] sortedArray,
            T target,
            Comparator<? super T> comparator) {
        return SearchContainer.<T>comparatorContainer(comparator)
                .searchAlgorithm()
                .search(sortedArray, target)
                .index();
    }

    public static void main(String[] args) {
        BinarySearchDemo.run(CONTAINER);
    }

    private static Integer[] toIntegerArray(int[] values) {
        if (values == null) {
            throw new IllegalArgumentException("sortedArray must not be null");
        }

        Integer[] boxedValues = new Integer[values.length];
        for (int index = 0; index < values.length; index++) {
            boxedValues[index] = values[index];
        }

        return boxedValues;
    }
}

import java.util.Comparator;

final class BinarySearcher<T> implements SearchAlgorithm<T> {
    private final Comparator<? super T> comparator;

    BinarySearcher(Comparator<? super T> comparator) {
        if (comparator == null) {
            throw new IllegalArgumentException("comparator must not be null");
        }

        this.comparator = comparator;
    }

    static <T extends Comparable<? super T>> BinarySearcher<T> naturalOrder() {
        return new BinarySearcher<T>(Comparator.naturalOrder());
    }

    @Override
    public SearchResult search(T[] sortedArray, T target) {
        validateInput(sortedArray, target);

        int low = 0;
        int high = sortedArray.length - 1;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            int comparison = comparator.compare(sortedArray[mid], target);

            if (comparison == 0) {
                return SearchResult.foundAt(mid);
            }

            if (comparison < 0) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        return SearchResult.notFound();
    }

    private static <T> void validateInput(T[] sortedArray, T target) {
        if (sortedArray == null) {
            throw new IllegalArgumentException("sortedArray must not be null");
        }

        if (target == null) {
            throw new IllegalArgumentException("target must not be null");
        }
    }
}
